function validate([ages]) {
  if (!Array.isArray(ages) || ages.length < 1 || ages.length > 20000) return 'ages needs 1 to 2 * 10^4 values.';
  if (ages.some(a => !Number.isInteger(a) || a < 1 || a > 120)) return 'Each age is a whole number from 1 to 120.';
  return null;
}

