function numFriendRequests(ages) {
  const count = new Array(121).fill(0);
  for (const age of ages) {
    count[age]++;
  }

  const prefix = new Array(121).fill(0);
  for (let age = 1; age <= 120; age++) {
    prefix[age] = prefix[age - 1] + count[age];
  }

  let requests = 0;
  for (let age = 1; age <= 120; age++) {
    const lowest = Math.floor(age / 2) + 8;
    if (count[age] === 0 || lowest > age) {
      continue;
    }
    const targets = prefix[age] - prefix[lowest - 1];
    requests += count[age] * (targets - 1);
  }
  return requests;
}

