function numFriendRequests(ages) {
  let total = 0;
  for (let x = 0; x < ages.length; x++) {
    for (let y = 0; y < ages.length; y++) {
      if (x === y) continue;
      if (ages[y] <= 0.5 * ages[x] + 7) continue;
      if (ages[y] > ages[x]) continue;
      if (ages[y] > 100 && ages[x] < 100) continue;
      total++;
    }
  }
  return total;
}

