function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 12);
  const mode = rand();
  const pick = () => {
    if (mode < 0.25) return 12 + Math.floor(rand() * 8);      // around the age-15 threshold
    if (mode < 0.5) return 95 + Math.floor(rand() * 12);      // around 100
    if (mode < 0.65) return 16 + Math.floor(rand() * 3);      // heavy duplicates
    return 1 + Math.floor(rand() * 120);
  };
  return [Array.from({ length: n }, pick)];
}
